tasks.solution:
boundary = 10
hits = set()
def classify(value):
    if value >= boundary: hits.add('high')
    else: hits.add('low')
inputs = [boundary - 1, boundary]
for value in inputs: classify(value)
print(inputs, sorted(hits))
